    guide_text_3103aec7649a7f3c: "获委任的地方委员会，在所属行政区内编号",
    guide_text_c47d5976501ed936: "多个行政区都有第7委员会，因此单凭编号不能标识委员会",
    guide_text_3a7d9400aa565aec: "社区委员会覆盖的区域",
