    public_input_explainer_open: "公众参与如何运作",
    public_input_explainer_what_html: "<p>参与公开程序意味着把内容留在官方记录上：在听证会上发言，或在公布的截止日期前提交书面意见。该记录随后起什么作用取决于具体程序，本站每条公告都会说明适用哪一种。</p>",
    public_input_explainer_destinations_heading: "您所说的内容最终去向何处",
    public_input_explainer_destinations_html: "<ul><li><b>公众意见记录</b>——在意见征询期内提交的书面意见，进入该机构必须考虑的记录。</li><li><b>听证证词</b>——您在听证会上所说的内容，进入该场听证会的证词记录。</li><li><b>逐字记录</b>——部分程序会公布会议的逐字记录。</li><li><b>会议纪要</b>——另一些机构改为公布事件经过的摘要。</li><li><b>决定文件</b>——单独的记录，在该机构作出决定并加以记录时公布。</li></ul><p>部分程序还会公布回应所收意见的报告。它是上述去向之一，每条公告都会说明是否适用。</p>",
    public_input_explainer_limits_heading: "参与的限度",
    public_input_explainer_limits_html: "<p>官员的答复与记录条目是两回事。提交意见或作证会把您的话写入记录，而没有任何官员必须亲自答复您。本站不承诺会有这样的答复。</p><p>意见的数量仍然只是数量。机构依据其适用的法律衡量所述内容，因此本站不把任何意见总数呈现为支持或反对，也不把意见数量当作投票。</p>",
    public_input_explainer_examples_heading: "三种实际运作方式",
    public_input_explainer_example_hearing: "在市议会关于某项法案的听证会上发言，或提交书面证词。",
    public_input_explainer_example_hearing_surface: "查看已排期的听证会和会议",
    public_input_explainer_example_rule: "在公布的截止日期前，对机构的拟议规则提出意见。",
    public_input_explainer_example_rule_surface: "查看开放中的规则意见征询期",
    public_input_explainer_example_contract: "在意见征询窗口期内，对拟议的中标（授予合同）提出意见。",
    public_input_explainer_example_contract_surface: "查看合同意见截止日期",
    public_input_explainer_official_source: "官方来源：{source}",
    public_input_explainer_method_summary: "这段说明的来源",
    public_input_explainer_method_html: "<p>上面每个例子都链接到管辖它的市政页面，以及本站列出该类现行记录的板块。这段说明描述这些程序的一般运作方式；任何一项的具体日期、状态、目的和参与渠道都留在它自己的公告上，旁边附有其市政公报来源链接。</p>",
