    stats_area_staten_island: "史坦顿岛",
    api_p_intro_html: "CityScroll 的每个视图都有一个机器可读的对应版本。无需密钥，无需账户；端点均有速率限制并已缓存，且不涉及任何付费服务。基础 URL： <code>https://api.cityscroll.org</code>。",
    api_h_feeds: "订阅源 — 将任何搜索导出为 RSS / JSON / 日历",
    api_p_feeds_html: "<code>GET /feed.xml</code>（Atom）· <code>GET /feed.json</code>（JSON Feed 1.1）· <code>GET /feed.ics</code>（可订阅日历 — 每条带日期的公告对应一个事件）。边缘缓存 15 分钟。",
    api_th_param: "参数",
    api_th_meaning: "含义",
    api_row_q: "关键词（最多4个）",
    api_row_agency: "机构名称（按记录中显示的写法）",
    api_row_min: "最低中标金额 $（资金视角 → 中标信息流）",
    api_row_kindname_html: "实体视角：<code>kind=vendor|agency</code>，<code>name=…</code> — 供应商名称按规范化词干匹配，因此包含后缀和大小写的变体",
    api_h_property_locations: "房产位置",
    api_p_property_locations_html: "<code>GET /property-locations</code> 返回最新的房产处置公告，并提供提取的现场地址、行政区、税务地块、BBL，以及可用时已解析的地图坐标。每日视图在边缘缓存 30 分钟。City Record Online 仍是权威来源。",
    api_h_agencies: "机构名称对照表",
    api_p_agencies_html: "<code>GET /agencies</code> 列出《市政公报》开放数据中原样记录的每个机构名称，并将其连接到本站使用的统一名称。添加 <code>?format=csv</code> 可获取 CSV。该端点无需密钥，允许跨站请求，并缓存一天。",
    api_agencies_dictionary_html: "<tr><td><code>raw_string</code></td><td><code>agency_name</code> 中的原文；来源中每个不同字符串占一行</td></tr><tr><td><code>canonical_id</code></td><td>对照表分配的稳定文本标识符</td></tr><tr><td><code>canonical_name</code></td><td>本站为该组使用的名称</td></tr><tr><td><code>variants</code></td><td>连接到同一标识符的所有来源拼写</td></tr>",
    api_p_agencies_limits: "匹配会参考大小写、标点、已知简称和行政隶属系列。新的拼写在对照表更新前可能拥有单独的标识符。该对照表用于连接记录，并非官方机构名录。",
    api_h_batch: "批量交叉核对",
    api_p_batch_html: "<code>POST /batch</code>，请求体为 <code>{\"names\": [\"…\", …]}</code>（每次请求最多10个名称，每个IP每天30次请求）。对每个名称返回：<b>awards</b> = 提及该供应商的中标（授予合同）/意向通知（按名称词干匹配，涵盖所有年份）；<b>mentions</b> = 最近两年各期市政公报的全文命中；<b>entity</b> = 存在中标（授予合同）时的供应商档案永久链接。",
    api_label_try: "试一下 — 每行一个名称",
